import re
EMO_RE = re.compile("(" + "|".join(sorted(map(re.escape, EMOJI), key=len, reverse=True)) + ")\uFE0F?")
ANY_EMO = re.compile("[\U0001F300-\U0001FAFF\u2600-\u26FF\u2700-\u27BF\u2B50]\uFE0F?")
def svg(name, cls="i"):
    return f'<svg class="{cls}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true" focusable="false">{P[name]}</svg>'
KEEP = set("✓✕✔")
def _text(s):
    def r(m):
        ch = m.group(1)
        return svg(EMOJI[ch])
    return EMO_RE.sub(r, s)
def _strip(s):
    s = EMO_RE.sub("", s)
    return re.sub(r"^\s+", "", s) if s.strip() else s
TAG = re.compile(r"(<!--.*?-->|<[^>]+>)", re.S)
RAW = ("script", "style", "textarea", "title", "option")
def svgify(html):
    out, raw = [], None
    for part in TAG.split(html):
        if not part: continue
        if part.startswith("<"):
            m = re.match(r"</?([a-zA-Z0-9]+)", part)
            if m:
                t = m.group(1).lower()
                if part.startswith("</"):
                    if raw == t: raw = None
                elif t in RAW and not part.endswith("/>"): raw = t
            # trong thuộc tính (aria-label, title, placeholder…) chỉ bỏ emoji
            out.append(EMO_RE.sub("", part) if not part.startswith("<!") else part)
        else:
            if raw in ("script", "style"): out.append(part)
            elif raw: out.append(EMO_RE.sub("", part).replace("  ", " "))
            else: out.append(_text(part))
    return "".join(out)
